/**
 * Generate and persist a password entirely inside the paired local bridge.
 *
 * The model supplies only public card metadata and a generation policy. The
 * generated bytes exist in this process long enough to be sealed/sent to the
 * atomic Agent Secret write, and never cross the model-facing tool boundary,
 * argv, a file, the local mirror, logs or the returned receipt.
 */
import crypto from "node:crypto";

import {
  BridgePairingRequiredError,
  BridgePluginUpgradeRequiredError,
  ensureBridgeCompatibility,
  ensureCompanyEncryptionContext,
  request,
  requireToken,
} from "./trelio-workspace.mjs";
import {
  buildLocalAgentSecretWrite,
  normalizeAgentSecretNewCard,
} from "./trelio-secret-chat.mjs";

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/iu;
const FIELD_KEY = /^[a-z][a-z0-9_]{0,63}$/u;
const PASSWORD_LENGTH_MIN = 16;
const PASSWORD_LENGTH_MAX = 128;
const PASSWORD_GROUPS = [
  "abcdefghijkmnopqrstuvwxyz",
  "ABCDEFGHJKLMNPQRSTUVWXYZ",
  "23456789",
  "!#$%&()*+,-./:;<=>?@[]^_{|}~",
];
const PASSWORD_ALPHABET = PASSWORD_GROUPS.join("");
const INPUT_KEYS = new Set([
  "secretId", "runId", "expectedCurrentVersion", "clientRequestId",
  "newSecret", "generatedFields", "userExplicitlyRequestedGeneratedPersistentStorage",
]);
const SAFE_NATIVE_FAILURES = new Map([
  ["TRELIO_RUNTIME_HOOK_REQUIRED", "Включите Hooks плагина Trelio Agent Workspaces и повторите запрос."],
  ["AGENT_RUNTIME_POLICY_NOT_SATISFIED", "Выберите разрешённую компанией модель и уровень reasoning, затем начните новую сессию с включёнными Hooks."],
  ["MCP_REAUTHORIZATION_REQUIRED", "Вызовите list_agent_secrets для исходной области через подключение Trelio: оно покажет штатное расширение OAuth-доступа. Сохраните ранее выданные scopes и повторите генерацию с тем же clientRequestId."],
]);

export class AgentSecretGenerateError extends Error {
  constructor(code, message) {
    super(message);
    this.code = code;
  }
}

const invalid = () => {
  // The failure is intentionally independent of public input details so it
  // stays safe if a future caller accidentally mixes in sensitive material.
  throw new AgentSecretGenerateError(
    "AGENT_SECRET_GENERATE_INPUT_INVALID",
    "Проверьте цель, password-поля, длину и явную просьбу сгенерировать и сохранить доступы.",
  );
};
const isRecord = (value) => Boolean(value && typeof value === "object" && !Array.isArray(value));
const boundedString = (value, maximum) => (
  typeof value === "string" && value.length > 0 && value.length <= maximum
);
const canonicalJson = (value) => JSON.stringify(
  value,
  function (_key, item) {
    if (!isRecord(item)) return item;
    return Object.fromEntries(Object.keys(item).sort().map((key) => [key, item[key]]));
  },
);

export const normalizeGeneratedAgentSecretInput = (input) => {
  if (
    !isRecord(input) || Object.keys(input).some((key) => !INPUT_KEYS.has(key))
    || input.userExplicitlyRequestedGeneratedPersistentStorage !== true
    || !UUID.test(input.runId || "")
    || !Number.isSafeInteger(input.expectedCurrentVersion) || input.expectedCurrentVersion < 0
    || !boundedString(input.clientRequestId, 255) || input.clientRequestId !== input.clientRequestId.trim()
    || Boolean(input.secretId) === Boolean(input.newSecret)
    || !Array.isArray(input.generatedFields) || input.generatedFields.length < 1 || input.generatedFields.length > 50
  ) invalid();
  if (input.secretId && !UUID.test(input.secretId)) invalid();
  let newSecret;
  if (input.newSecret) {
    try {
      newSecret = normalizeAgentSecretNewCard(input.newSecret, input.expectedCurrentVersion);
    } catch {
      invalid();
    }
  }
  const keys = new Set();
  const generatedFields = input.generatedFields.map((field) => {
    if (
      !isRecord(field) || Object.keys(field).some((key) => !["key", "generator", "length"].includes(key))
      || !FIELD_KEY.test(field.key || "") || keys.has(field.key)
      || field.generator !== "password"
      || !Number.isSafeInteger(field.length)
      || field.length < PASSWORD_LENGTH_MIN || field.length > PASSWORD_LENGTH_MAX
    ) invalid();
    keys.add(field.key);
    return { key: field.key, generator: "password", length: field.length };
  });
  if (newSecret && (
    generatedFields.some((field) => !newSecret.fields.some((candidate) => (
      candidate.key === field.key && candidate.type === "password"
    )))
    || newSecret.fields.some((field) => field.required && !keys.has(field.key))
  )) invalid();
  return { ...input, ...(newSecret ? { newSecret } : {}), generatedFields };
};

const buildGenerationKey = ({ context, companyEncryption, token }) => {
  const key = context.storageMode === "company_e2ee"
    ? Buffer.from(companyEncryption?.scopePrivateEncryptionKey?.privateJwk?.d || "", "base64url")
    : Buffer.from(token || "", "utf8");
  if (!key.length) invalid();
  return key;
};

const createDeterministicIndexSource = (key, seed) => {
  let block = Buffer.alloc(0);
  let offset = 0;
  let counter = 0;
  const nextByte = () => {
    if (offset >= block.length) {
      // HMAC expansion makes an ambiguous retry reproduce the same password
      // without persisting plaintext. Each request is separated by the exact
      // company/member/card/Run/version/policy seed assembled by the caller.
      block.fill(0);
      const counterBytes = Buffer.allocUnsafe(4);
      counterBytes.writeUInt32BE(counter++);
      block = crypto.createHmac("sha256", key)
        .update("trelio:generated-agent-secret-password:v1\0")
        .update(seed)
        .update(counterBytes)
        .digest();
      offset = 0;
    }
    return block[offset++];
  };
  return {
    next(length) {
      // Rejection sampling avoids modulo bias for alphabets whose length does
      // not divide 256, including the combined password alphabet.
      const ceiling = Math.floor(256 / length) * length;
      let byte = nextByte();
      while (byte >= ceiling) byte = nextByte();
      return byte % length;
    },
    dispose() {
      block.fill(0);
      offset = 0;
    },
  };
};

export const generateDeterministicPassword = ({ key, seed, length }) => {
  const source = createDeterministicIndexSource(key, seed);
  try {
    // Force one character from every class, then shuffle the entire result so
    // class positions reveal nothing and downstream password rules stay met.
    const characters = PASSWORD_GROUPS.map((group) => group[source.next(group.length)]);
    while (characters.length < length) {
      characters.push(PASSWORD_ALPHABET[source.next(PASSWORD_ALPHABET.length)]);
    }
    for (let index = characters.length - 1; index > 0; index--) {
      const other = source.next(index + 1);
      [characters[index], characters[other]] = [characters[other], characters[index]];
    }
    return characters.join("");
  } finally {
    source.dispose();
  }
};

export const buildGeneratedAgentSecretWrite = async ({ input, context, companyEncryption, token }) => {
  const fields = input.newSecret?.fields ?? context.fields;
  if (
    !Array.isArray(fields) || fields.length < 1 || fields.length > 50
    || fields.some((field) => (
      !FIELD_KEY.test(field.key || "") || typeof field.required !== "boolean"
    ))
    || new Set(fields.map((field) => field.key)).size !== fields.length
  ) invalid();
  const requested = new Map(input.generatedFields.map((field) => [field.key, field]));
  if (
    requested.size !== input.generatedFields.length
    || input.generatedFields.some((field) => !fields.some((candidate) => (
      candidate.key === field.key && candidate.type === "password"
    )))
    || fields.some((field) => field.required && !requested.has(field.key))
  ) invalid();

  // Normalize generation order to the schema, so a semantically identical
  // retry does not change the derived bytes merely because JSON array order did.
  const policy = fields.flatMap((field) => requested.has(field.key) ? [requested.get(field.key)] : []);
  const key = buildGenerationKey({ context, companyEncryption, token });
  const values = {};
  try {
    const commonSeed = canonicalJson({
      companyId: context.companyId,
      memberId: context.companyMemberId,
      secretId: context.secretId,
      runId: input.runId,
      expectedCurrentVersion: input.expectedCurrentVersion,
      clientRequestId: input.clientRequestId,
      newSecret: input.newSecret ?? null,
      policy,
    });
    for (const field of policy) {
      values[field.key] = generateDeterministicPassword({
        key,
        seed: `${commonSeed}\0${field.key}\0${field.length}`,
        length: field.length,
      });
    }
  } finally {
    key.fill(0);
  }
  return buildLocalAgentSecretWrite({
    input, context, companyEncryption, token, values, source: "generated",
  });
};

export const handleGeneratedAgentSecretSave = async (
  origin,
  rawInput,
  {
    signal,
    getToken = requireToken,
    checkCompatibility = ensureBridgeCompatibility,
    getEncryptionContext = ensureCompanyEncryptionContext,
    sendRequest = request,
  } = {},
) => {
  try {
    signal?.throwIfAborted();
    const input = normalizeGeneratedAgentSecretInput(rawInput?.arguments);
    const companySlug = rawInput?.companySlug;
    if (!boundedString(companySlug, 120) || companySlug !== companySlug.trim() || rawInput.localFilePath !== undefined) invalid();
    const token = await getToken(origin, { onStatus: () => undefined, signal });
    await checkCompatibility(origin, token, { signal });
    const query = new URLSearchParams({
      companySlug, runId: input.runId, clientRequestId: input.clientRequestId,
      ...(input.newSecret
        ? { scopeType: input.newSecret.scopeType, scopeId: input.newSecret.scopeId }
        : { secretId: input.secretId }),
    });
    const context = await (await sendRequest(
      origin,
      token,
      "/api/agent-secrets/generated-save-context?" + query,
      { signal },
    )).json();
    if (context.companySlug !== companySlug) invalid();
    let companyEncryption = null;
    if (context.storageMode === "company_e2ee") {
      try {
        companyEncryption = await getEncryptionContext({
          origin, token, company: { id: context.companyId, slug: companySlug },
        });
      } catch {
        throw new AgentSecretGenerateError(
          "AGENT_SECRET_DEVICE_NOT_READY",
          "Локальное устройство не готово к шифрованию. Проверьте его доступ в настройках шифрования компании, затем повторите генерацию с тем же clientRequestId.",
        );
      }
    }
    const transport = await buildGeneratedAgentSecretWrite({
      input, context, companyEncryption, token,
    });
    signal?.throwIfAborted();
    const result = await (await sendRequest(
      origin,
      token,
      "/api/agent-workspaces/company-context/" + encodeURIComponent(companySlug) + "/actions/execute",
      {
        method: "POST", headers: { "content-type": "application/json" }, signal,
        body: JSON.stringify({
          nativeTool: "generate_agent_secret", arguments: transport,
          ...(rawInput.runtimeSessionProof ? { runtimeSessionProof: rawInput.runtimeSessionProof } : {}),
        }),
      },
    )).json();
    const outcome = result.structuredContent;
    if (result.isError && SAFE_NATIVE_FAILURES.has(outcome?.code)) {
      throw new AgentSecretGenerateError(outcome.code, SAFE_NATIVE_FAILURES.get(outcome.code));
    }
    if (
      result.isError || outcome?.ok !== true || outcome.secret?.id !== context.secretId
      || outcome.secret?.storageMode !== context.storageMode || outcome.secret?.hasValue !== true
      || outcome.secret?.currentVersion !== input.expectedCurrentVersion + 1
    ) {
      throw new AgentSecretGenerateError(
        "AGENT_SECRET_GENERATE_SAVE_REJECTED",
        "Генерация и сохранение не подтверждены. Проверьте разрешения, активный запуск и текущую версию карточки; повтор использует тот же clientRequestId.",
      );
    }
    const safe = {
      ok: true,
      secret: {
        id: context.secretId,
        storageMode: context.storageMode,
        currentVersion: outcome.secret.currentVersion,
        hasValue: true,
      },
      replayed: outcome.replayed === true,
      setupUrl: new URL(
        "/" + encodeURIComponent(companySlug) + "/agent-secrets/" + context.secretId + "/setup/",
        origin,
      ).href,
    };
    return {
      structuredContent: safe,
      content: [{ type: "text", text: "Пароль сгенерирован и сохранён. Значение не раскрывалось модели." }],
    };
  } catch (error) {
    if (error instanceof BridgePairingRequiredError || error instanceof BridgePluginUpgradeRequiredError) {
      throw error;
    }
    const safe = error instanceof AgentSecretGenerateError
      ? { code: error.code, message: error.message }
      : {
          code: "AGENT_SECRET_GENERATE_SAVE_UNCONFIRMED",
          message: error?.statusCode === 403
            ? "Нет разрешения на генерацию и сохранение. Проверьте права на карточку, активный запуск и доступ локального устройства."
            : "Генерация и сохранение не подтверждены. Проверьте подключение, локальное устройство и текущую карточку перед повтором с тем же clientRequestId.",
        };
    return { isError: true, structuredContent: safe, content: [{ type: "text", text: safe.message }] };
  }
};
